/* ComboFlow v1.14: live demo feed, kitchen status panel and counter order intent. Simulated; no live KDS, no learned AI. */
const LIVE_TICK_MS=1500,LIVE_DT=15,DEMO_START=11*3600+30*60;
let liveOn=true,feedLost=false,feed=KP.seedHistory(KP.liveWorld({arrivalRate})),statusOpen=false,statusTab='overview',pinnedRec=null,pointerDown=false;
addEventListener('pointerdown',()=>{pointerDown=true;},true);
addEventListener('pointerup',()=>setTimeout(()=>{pointerDown=false;},0),true);

// ---------- Live demo feed ----------
function demoClock(offset=0){const t=((DEMO_START+feed.clock+offset)%86400+86400)%86400;return String(Math.floor(t/3600)).padStart(2,'0')+':'+String(Math.floor(t%3600/60)).padStart(2,'0');}
function liveActive(){return liveOn&&(s.channel==='kitchen'||s.channel==='pos');}
function liveBadge(){return feedLost?'<span class="live-badge lost">⚠ SIGNAL LOST · rules only</span>':liveActive()?`<span class="live-badge on"><i></i>DEMO LIVE ×10 · ${demoClock()}</span>`:`<span class="live-badge paused">❚❚ PAUSED · ${demoClock()}</span>`;}
function liveTick(){
 if(!liveActive()||document.hidden||page==='done')return;
 const before=E.band(s);feed.arrivalRate=arrivalRate;
 const r=KP.liveStep(feed,kitchenTickets,ingredientStock,LIVE_DT);feed=r.world;kitchenTickets=r.tickets;ingredientStock=r.stock;
 for(const id in readyExtras)if(readyExtras[id]>0)readyAge[id]+=LIVE_DT;
 s.freshness=feedLost?s.freshness+LIVE_DT:0;
 syncKitchen(LIVE_DT,true);
 for(const e of r.events)if(e.type==='delivery')log('scheduled_delivery_simulated',{received:e.got});
 const after=E.band(s);
 if(before!==after){log('kitchen_band_changed',{from:before,to:after,source:'live_demo'});const keep=notice;revalidate();if(notice==='Options have been updated for this simulated scenario.'||notice===keep)notice=`Kitchen signal is now ${after} (demo feed). Suggestions were re-checked.`;}
 const a=document.activeElement;if(pointerDown||(a&&['INPUT','SELECT','TEXTAREA'].includes(a.tagName)))return;
 render();
}
setInterval(liveTick,LIVE_TICK_MS);
function toggleLive(){liveOn=!liveOn;log('live_demo_toggled',{on:liveOn});render();}
function toggleSignalLoss(on){feedLost=on;if(!on)s.freshness=0;else s.freshness=Math.max(s.freshness,61);log('signal_loss_simulated',{on});revalidate();render();}
function setCrew(n){if(![2,3,4].includes(n))return;feed.crewSlots=n;log('demo_crew_changed',{slots:n});render();}
function resetLiveDemo(){kitchenTickets=seedKitchen(45);ingredientStock=KP.stockDefaults();incomingStock={};feed=KP.seedHistory(KP.liveWorld({arrivalRate,crewSlots:feed.crewSlots}));feedLost=false;s.freshness=0;s.previousHigh=false;s.highSeconds=0;s.recoverySeconds=0;syncKitchen();log('live_demo_reset');revalidate();render();}

// ---------- Trend chart: last 60 demo minutes (+ optional 15-minute what-if projection) ----------
function trendChart({forecast=null,w=560,h=220,cls='forecast-chart trend-chart'}={}){
 const raw=feed.history.filter(x=>x.clock>feed.clock-3600),buckets={};for(const x of raw){const k=Math.ceil((x.clock-feed.clock)/60);(buckets[k]=buckets[k]||[]).push(x);}
 const hist=Object.entries(buckets).map(([k,xs])=>({clock:feed.clock+Number(k)*60,open:xs.reduce((n,x)=>n+x.open,0)/xs.length,age:xs.reduce((n,x)=>n+x.age,0)/xs.length})).sort((a,b)=>a.clock-b.clock),L=34,R=w-62,T=14,B=h-30,xmin=-60,xmax=forecast?15:0;
 const X=m=>L+(m-xmin)/(xmax-xmin)*(R-L),rel=x=>(x.clock-feed.clock)/60;
 const maxOpen=Math.max(6,...hist.map(x=>x.open),...(forecast||[]).map(x=>x.high)),maxAge=Math.max(150,...hist.map(x=>x.age));
 const Yo=v=>B-v/maxOpen*(B-T),Ya=v=>B-v/maxAge*(B-T),f=n=>n.toFixed(1);
 const openLine=hist.map(x=>f(X(rel(x)))+','+f(Yo(x.open))).join(' '),ageLine=hist.map(x=>f(X(rel(x)))+','+f(Ya(x.age))).join(' ');
 const area=hist.length?`<polygon points="${f(X(rel(hist[0])))},${B} ${openLine} ${f(X(rel(hist.at(-1))))},${B}" fill="url(#trendFill)"/>`:'';
 const last=hist.at(-1),ticks=forecast?[-60,-45,-30,-15,0,15]:[-60,-45,-30,-15,0];
 const proj=forecast&&forecast.length?`<polygon points="${forecast.map(p=>f(X(p.min))+','+f(Yo(p.high))).join(' ')} ${[...forecast].reverse().map(p=>f(X(p.min))+','+f(Yo(p.low))).join(' ')}" fill="#ed1537" opacity=".1"/><polyline points="${forecast.map(p=>f(X(p.min))+','+f(Yo(p.base))).join(' ')}" fill="none" stroke="#e41b35" stroke-width="2" stroke-dasharray="5 4"/>`:'';
 return `<svg class="${cls}" viewBox="0 0 ${w} ${h}" role="img" aria-label="Last 60 demo minutes: open tickets and median waiting-ticket age${forecast?', plus a 15-minute what-if projection':''}. Simulated feed."><defs><linearGradient id="trendFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#ed1537" stop-opacity=".22"/><stop offset="100%" stop-color="#ed1537" stop-opacity=".02"/></linearGradient></defs>`
 +[0,.5,1].map(v=>`<line x1="${L}" y1="${f(Yo(maxOpen*v))}" x2="${R}" y2="${f(Yo(maxOpen*v))}" stroke="#eee9e5"/><text x="${L-6}" y="${f(Yo(maxOpen*v)+4)}" text-anchor="end">${Math.round(maxOpen*v)}</text>`).join('')
 +[[90,'Elevated 90s'],[120,'High 120s']].map(([v,t])=>`<line x1="${L}" y1="${f(Ya(v))}" x2="${R}" y2="${f(Ya(v))}" stroke="${v===90?'#c98a12':'#c3112c'}" stroke-dasharray="3 4" opacity=".7"/><text class="thr" x="${R+4}" y="${f(Ya(v)+3)}">${t}</text>`).join('')
 +area+`<polyline points="${openLine}" fill="none" stroke="#e41b35" stroke-width="2.6" stroke-linejoin="round"/><polyline points="${ageLine}" fill="none" stroke="#e39b16" stroke-width="2" stroke-linejoin="round"/>`+proj
 +`<line x1="${f(X(0))}" y1="${T}" x2="${f(X(0))}" y2="${B}" stroke="#3a3a3a" stroke-dasharray="2 3" opacity=".5"/>`
 +(last?`<circle class="now-dot" cx="${f(X(0))}" cy="${f(Yo(last.open))}" r="4.5" fill="#e41b35"/><circle cx="${f(X(0))}" cy="${f(Ya(last.age))}" r="3.5" fill="#e39b16"/>`:'')
 +ticks.map(m=>`<text x="${f(X(m))}" y="${h-12}" text-anchor="middle">${m===0?'Now '+demoClock():demoClock(m*60)}</text>`).join('')
 +`<g class="legend" transform="translate(${L+6},${T+4})"><rect width="10" height="3" y="3" fill="#e41b35"/><text x="14" y="8">Open tickets</text><rect x="96" width="10" height="3" y="3" fill="#e39b16"/><text x="110" y="8">Median waiting age (s)</text>${forecast?'<rect x="246" width="10" height="3" y="3" fill="#e41b35" opacity=".5"/><text x="260" y="8">What-if projection</text>':''}</g></svg>`;
}

// ---------- Kitchen status panel (shared by Kitchen Board and Staff POS) ----------
const bandCopy={Normal:['Kitchen steady','Full suggestion set: up to 3 combos + 1 compatible extra.','✓'],Elevated:['Kitchen busy','Ready items and short-prep extras first; slower extras drop down.','!'],High:['Kitchen at High load','Every upsell paused. Main meals only. Keep taking orders.','⏱'],'Safe fallback':['Signal unavailable','Rules-only fixed order. No workload ranking or speed claims.','⚠']};
function openStatus(tab='overview'){statusOpen=true;statusTab=tab;log('kitchen_status_opened',{tab,channel:s.channel});render();}
function closeStatus(){statusOpen=false;render();}
function setStatusTab(t){statusTab=t;render();}
function sessionStats(){const c=k=>events.filter(e=>e.event===k).length,shown=events.filter(e=>e.event==='recommendation_shown'),confirms=events.filter(e=>e.event==='confirm');
 return {shown:shown.filter(e=>!e.no_recommendation).length,none:shown.filter(e=>e.no_recommendation).length,add:c('add'),skip:c('skip'),blocked:c('review_blocked'),picks:c('pos_pick_added'),confirms:confirms.length,kiosk:confirms.filter(e=>e.channel==='kiosk').length,pos:confirms.filter(e=>e.channel==='pos').length,total:confirms.reduce((n,e)=>n+(e.final_order?.total||0),0),bandChanges:c('kitchen_band_changed'),deliveries:c('scheduled_delivery_simulated')};}
function statusMetrics(){const open=kitchenTickets.filter(t=>t.status!=='ready'),arrived=feed.history.slice(-40).reduce((n,h)=>n+h.arrived,0);
 return `<div class="ops-metrics"><div><small>Orders preparing</small><b>${kitchenTickets.filter(t=>t.status==='preparing').length}</b></div><div><small>Open tickets</small><b>${open.length}</b></div><div><small>Median waiting-ticket age</small><b>${s.age}<i>s</i></b><span class="meter"><span style="width:${Math.min(100,s.age/1.5)}%"></span></span></div><div><small>Arrivals · last 10 demo min</small><b>${arrived}</b></div></div>`;}
function statusBody(){const band=E.band(s),[title,desc,icon]=bandCopy[band],p=kitchenPlan(),st=sessionStats();
 if(statusTab==='kitchen'){const loads=KP.workload(kitchenTickets),max=Math.max(1,...loads.map(x=>x.total)),watch=p.inventory.filter(i=>i.free<0||(i.cover!==null&&i.cover<5));
  return `<h3>Station workload <small>recipe units · not utilization</small></h3><div class="ops-bars">${loads.map(l=>`<div><span>${l.name}</span><i><b style="width:${l.total/max*100}%"></b></i><em>${l.queued} queued · ${l.preparing} prep</em></div>`).join('')}</div><h3>Ingredients to watch</h3><div class="ops-list">${watch.map(i=>`<span><b>${i.name}</b>${i.onHand} on hand · ${i.reserved} queued${i.free<0?' · short':''}</span>`).join('')||'<span>No shortage in this scenario.</span>'}</div><h3>Ready to pair</h3><div class="ops-list">${Object.entries(readyExtras).map(([id,n])=>`<span><b>${E.addons.find(x=>x.id===id).name}</b>${n} portions${readyDue(id)?' · re-check due':''}</span>`).join('')}</div><div class="actions"><button class="btn white" onclick="closeStatus();switchChannel('kitchen')">Open Kitchen Board →</button><button class="btn white" onclick="closeStatus();openKitchenPanel('ready')">Manage ready items</button></div>`;}
 if(statusTab==='suggestions'){const pos=E.band({...s})==='High'?'Paused':'One kitchen-aware extra';
  return `<h3>What customers and staff see now</h3><div class="ops-list"><span><b>Customer Kiosk</b>${band==='High'?'Top 3 main meals (Ready / Short prep only) · extras paused':band==='Safe fallback'?'Fixed valid order · extras paused':'Top 3 combos + 1 optional extra'}</span><span><b>Staff POS</b>${band==='High'?'No extra · continue the order':band==='Safe fallback'?'Fixed valid extra with staff check':pos+' · ready items first'}</span><span><b>Customer display</b>${band==='High'||band==='Safe fallback'?'Order and total only':'Undecided extra shown as NOT ADDED'}</span></div><h3>This demo session</h3><div class="ops-metrics small"><div><small>Suggestions shown</small><b>${st.shown}</b></div><div><small>ADD</small><b>${st.add}</b></div><div><small>SKIP</small><b>${st.skip}</b></div><div><small>No recommendation</small><b>${st.none}</b></div></div><p class="micro">Counts come from this browser’s event log only. They are not research results.</p>`;}
 if(statusTab==='reports'){const rate=st.add+st.skip?Math.round(st.add/(st.add+st.skip)*100)+'%':'—';
  return `<h3>Session report <small>this browser only · not research results</small></h3><div class="ops-metrics small"><div><small>Confirmed demo orders</small><b>${st.confirms}</b><span>${st.kiosk} kiosk · ${st.pos} counter</span></div><div><small>Illustrative order value</small><b>${money(st.total)}</b></div><div><small>ADD share of decisions</small><b>${rate}</b><span>${st.add} ADD · ${st.skip} SKIP</span></div><div><small>Load band changes</small><b>${st.bandChanges}</b><span>${st.deliveries} simulated deliveries</span></div></div><p class="micro">No revenue, waste, speed or accuracy claim. Export the log to analyse it with the blank validation template.</p><div class="actions"><button class="btn white" onclick="exportLog()">Export session log ↓</button></div>`;}
 if(statusTab==='settings')
  return `<h3>Demo feed</h3><div class="ops-settings"><label>Live demo<button class="btn ${liveOn?'red':'white'}" onclick="toggleLive()">${liveOn?'❚❚ Pause':'▶ Resume'}</button></label><label>Arrivals / min<select onchange="changeForecast('arrival',this.value)">${[0.6,1.2,2.4].map(v=>`<option value="${v}" ${arrivalRate===v?'selected':''}>${v} · ${v===0.6?'Quiet':v===1.2?'Steady':'Rush'}</option>`).join('')}</select></label><label>Demo crew slots<select onchange="setCrew(Number(this.value))">${[2,3,4].map(v=>`<option value="${v}" ${feed.crewSlots===v?'selected':''}>${v} parallel tickets</option>`).join('')}</select></label><label class="check"><input type="checkbox" ${feedLost?'checked':''} onchange="toggleSignalLoss(this.checked)">Simulate signal loss (Safe fallback)</label></div><p class="micro">Demo clock runs ×10 (15 demo seconds every 1.5 s) while Staff POS or Kitchen Board is open. Arrivals follow a seeded 30-minute wave; a simulated crew starts and finishes background tickets only; confirmed demo orders wait for your Start / Mark ready. Deliveries every 2 demo minutes restore stock. All [Assumption]; not a capacity model or wait promise.</p><div class="actions"><button class="btn white" onclick="refreshKitchen()">Refresh signal ↻</button><button class="btn white" onclick="resetLiveDemo()">Reset demo kitchen</button></div>`;
 return `<div class="ops-status ${band.replace(' ','-').toLowerCase()}"><span>${icon}</span><div><b>${title}</b><small>${desc}</small></div></div>${statusMetrics()}<div class="ops-chart"><h3>Trend · last 60 demo minutes <small>1-minute averages · ${feedLost?'feed paused':'updates every 15 demo s'}</small></h3>${trendChart({w:640,h:230,cls:'ops-trend'})}</div><p class="micro">Primary load signal: median waiting-ticket age. Bands are shadow-mode assumptions; no utilization percentage or customer wait estimate is shown.</p>`;}
function renderStatusPanel(){let root=$('opsRoot');if(!root){root=document.createElement('div');root.id='opsRoot';document.body.appendChild(root);}
 if(!statusOpen){root.innerHTML='';return;}
 const prev=root.querySelector('.ops-main'),top=prev?prev.scrollTop:0,band=E.band(s);
 root.innerHTML=`<dialog id="opsPanel" class="ops-dialog" oncancel="event.preventDefault();closeStatus()"><aside class="ops-nav"><div class="ops-logo"><img src="assets/kfc-logo.svg" alt="KFC"><b>ComboFlow</b></div>${[['overview','▦','Overview'],['kitchen','♨','Kitchen'],['suggestions','✦','Suggestions'],['reports','▤','Reports'],['settings','⚙','Settings']].map(([k,i,t])=>`<button class="${statusTab===k?'active':''}" onclick="setStatusTab('${k}')"><span>${i}</span>${t}</button>`).join('')}<small>Simulated feed<br>No live KDS</small></aside><section class="ops-main"><header><div><p class="eyebrow">KITCHEN STATUS · ${s.channel==='pos'?'STAFF POS':'KITCHEN BOARD'}</p><h2>Kitchen status</h2></div>${liveBadge()}<button class="ops-close" aria-label="Close kitchen status" onclick="closeStatus()">×</button></header>${statusBody()}</section><aside class="ops-gate"><h3>Load Gate setup</h3>${['Normal','Elevated','High','Safe fallback'].map(b=>`<button class="${band===b?'selected':''}" onclick="setBand('${b}')"><span class="gate-icon ${b.replace(' ','-').toLowerCase()}">${bandCopy[b][2]}</span><span><b>${b}</b><small>${bandCopy[b][1]}</small></span></button>`).join('')}<p class="ops-note">ⓘ Preview buttons load a scripted snapshot, then the demo feed continues from it. Thresholds and rules are placeholders to be tuned with pilot data.</p><small class="verify">${E.VERIFY}</small></aside></dialog>`;
 const d=$('opsPanel');d.showModal();const m=d.querySelector('.ops-main');if(m)m.scrollTop=top;
}

// ---------- Staff POS: order intent and up to three starting picks ----------
function setPOSIntent(key,value){const ok={party:[1,2,4],orderType:['meal','snack','sharing'],priority:['fast','full','value']}[key];if(!ok||!ok.includes(value)||page!=='pos')return;s[key]=value;pinnedRec=null;log('pos_intent_changed',{field:key,value});revalidate();render();}
function addPick(id){const picks=E.posPicks(s),i=picks.findIndex(x=>x.id===id);if(page!=='pos'||i<0){toast('This pick is no longer valid.');render();return;}log('pos_pick_added',{id,position:i+1,label:picks[i].label});changePOS(id,1);}
function posIntentPanel(){const picks=E.posPicks(s),chip=(key,v,t)=>`<button class="${s[key]===v?'selected':''}" aria-pressed="${s[key]===v}" ${page==='review'?'disabled':''} onclick="setPOSIntent('${key}',${typeof v==='number'?v:`'${v}'`})">${t}</button>`;
 return `<section class="pos-intent"><div class="section-number"><b>1</b><h3>Customer needs</h3><span>3 quick questions · staff asks</span></div><div class="pos-questions"><div><small>1 · WHO’S EATING?</small><div class="chip-row">${chip('party',1,'Just one')}${chip('party',2,'Two')}${chip('party',4,'Four')}</div></div><div><small>2 · ORDER TYPE?</small><div class="chip-row">${chip('orderType','meal','Meal')}${chip('orderType','snack','Snack')}${chip('orderType','sharing','Sharing')}</div></div><div><small>3 · PRIORITY?</small><div class="chip-row">${chip('priority','fast','Fastest')}${chip('priority','full','Best Fit')}${chip('priority','value','Best Value')}</div></div></div>${picks.length?`<div class="pos-picks"><p class="eyebrow">TOP PICKS FOR THESE NEEDS · TAP TO ADD</p><div class="pos-pick-grid">${picks.map((x,i)=>`<button class="pos-pick ${i?'':'featured'}" ${page==='review'?'disabled':''} onclick="addPick('${x.id}')"><div class="food-art">${foodPhoto(x.id)}</div><span><small>${escapeHTML(x.label)}</small><strong>${x.name}</strong><b>${money(x.price)}</b></span><i>Add →</i></button>`).join('')}</div><small class="verify">Up to three picks · same Rules and Load Gate as the kiosk · nothing is added until staff taps · ${E.VERIFY}</small></div>`:`<p class="micro pos-intent-note">${E.posHasBase(s)?'Basket started. ComboFlow now looks for one compatible extra for these needs.':'No valid pick for these needs right now. Use the menu.'}</p>`}</section>`;}
// Keep the shown extra stable while it stays eligible for the same basket and needs, so the live feed does not reshuffle it mid-conversation.
function posRec(d){if(posDecision||!d.cards.length)return null;const key=JSON.stringify([s.posLines,s.party,s.orderType,s.priority]);if(pinnedRec&&pinnedRec.key===key){const keep=d.eligible.find(x=>x.id===pinnedRec.id);if(keep)return {...keep,label:d.cards[0].label};}pinnedRec={key,id:d.cards[0].id};return d.cards[0];}
function customerPicks(){const picks=E.posPicks(s);return picks.length?`<div class="customer-picks"><small>TOP PICKS FOR YOU · NOT ADDED</small>${picks.map(x=>`<div><img src="${assetUrls[photoMap[x.id]||'chicken-combo.jpg']}" alt=""><span><b>${escapeHTML(x.name)}</b><em>${escapeHTML(x.label)}</em></span><strong>${money(x.price)}</strong></div>`).join('')}<span>Tell our team which one you’d like.</span></div>`:'';}

// Preserve open <details> and dialog scroll across full re-renders (live ticks re-render every 1.5 s).
const baseRender=render;
render=function(){const before=[...document.querySelectorAll('#app details,#lab details')].map(d=>d.open),dlg=document.querySelector('#app dialog[open]'),top=dlg?dlg.scrollTop:0;
 baseRender();
 const after=[...document.querySelectorAll('#app details,#lab details')];if(after.length===before.length)after.forEach((d,i)=>{d.open=before[i];});
 const nd=document.querySelector('#app dialog[open]');if(nd)nd.scrollTop=top;
 renderStatusPanel();};
render();
